import { type ImagePartKind } from '../manifest/primitives.schema.js';

export const PART_PORT = 3000;

const HEALTH_PROBE =
  `fetch('http://127.0.0.1:${PART_PORT}/health')` +
  '.then((r) => process.exit(r.status === 200 || r.status === 503 ? 0 : 1), () => process.exit(1))';

// The one recipe for a Node server part; the staged context holds deps/ (npm ci) and app/ (code).
export const serverPartRecipe = (part: ImagePartKind): string =>
  [
    '# syntax=docker/dockerfile:1',
    '# Generated by @agentage/extension build. Extension authors never write a Dockerfile.',
    'FROM node:26-alpine AS deps',
    'WORKDIR /app',
    'COPY deps/ ./',
    'RUN npm ci --omit=dev --no-audit --no-fund && npm cache clean --force',
    '',
    'FROM node:26-alpine AS runner',
    'ARG COMMIT_SHA',
    'ARG BUILD_TIME',
    'ARG IMAGE',
    'ENV NODE_ENV=production \\',
    '    NODE_OPTIONS=--enable-source-maps \\',
    `    PORT=${PART_PORT} \\`,
    '    COMMIT_SHA=$COMMIT_SHA \\',
    '    BUILD_TIME=$BUILD_TIME \\',
    '    AGENTAGE_IMAGE=$IMAGE',
    'WORKDIR /app',
    'COPY --from=deps /app/node_modules ./node_modules',
    'COPY app/ ./',
    'USER node',
    `EXPOSE ${PART_PORT}`,
    `HEALTHCHECK --interval=10s --timeout=3s --start-period=15s --retries=3 CMD ["node", "-e", "${HEALTH_PROBE}"]`,
    `CMD ["node", "node_modules/@agentage/extension/dist/runtime/main.js", "${part}"]`,
    '',
  ].join('\n');
